INSERT INTO linhas
(nome, resumo, pdf_path, orientador, orientandos, objetivos)
VALUES

(
    'Observatório de direitos sociais da população do Centro-Sul Fluminense',
    'Esta linha de pesquisa dedica-se à análise contínua da oferta de serviços públicos relacionados à garantia dos direitos sociais na área de influência do Campus Engenheiro Paulo de Frontin do IFRJ. Por meio da análise de dados, pesquisas documentais e revisões bibliográficas, busca compreender as condições de acesso da população a esses serviços e acompanhar sua relação com a efetivação dos direitos sociais.',
    NULL,
    'Rodrigo dos Santos Borges, Doutor em Geografia (UERJ), com mestrado em Geografia (UERJ) e mestrado em Humanidades Digitais (UFRRJ). Atua como professor no IFRJ e, na linha de pesquisa, atua na orientação científica, no planejamento metodológico e na coordenação das atividades.',
    'João Guilherme Huguenin Jacarandá e Vinícius Baptista Rocha. Atuam na coleta de dados, sistematização de informações, produção de materiais, apoio às ações acadêmicas e desenvolvimento tecnológico.',
    'Estudar e monitorar os direitos sociais fundamentais da população da região Centro-Sul Fluminense, abrangendo saúde, educação, habitação, trabalho e seguridade social, com foco na análise de políticas públicas e indicadores sociais.'
),

(
    'Laboratório de Políticas Institucionais',
    'O Laboratório de Políticas Institucionais dedica-se à análise e à avaliação contínua das políticas, diretrizes e práticas institucionais do IFRJ Campus Engenheiro Paulo de Frontin. Fundamentado na Lei nº 11.892/2008 e nos documentos orientadores da Rede Federal de Educação Profissional, Científica e Tecnológica, busca acompanhar a atuação institucional, contribuir para a qualificação da oferta educacional e fortalecer a transparência e o controle social. A iniciativa também considera o papel do campus na formação cidadã dos estudantes e no desenvolvimento local e regional.',
    NULL,
    'Rodrigo dos Santos Borges, Doutor em Geografia (UERJ), com mestrado em Geografia (UERJ) e mestrado em Humanidades Digitais (UFRRJ). Atua como professor no IFRJ e, na linha de pesquisa, atua na orientação científica, no planejamento metodológico e na coordenação das atividades.',
    'Elena Silveira Vargas e Giovanna da Cunha Passos Gonçalves. Atuam na coleta de dados, sistematização de informações, produção de materiais e apoio às ações acadêmicas.',
    'Analisar e avaliar continuamente as políticas e práticas do IFRJ para atender a população ao seu redor, qualificar a oferta educacional, fortalecer a transparência e o controle social e promover a formação cidadã e o desenvolvimento local e regional.'
),

(
    'Cultura Maker e Educação',
    'Esta linha de pesquisa investiga possibilidades de integração da cultura maker aos processos de ensino e aprendizagem, valorizando a experimentação, a criatividade e a resolução de problemas práticos. Busca desenvolver estratégias para a implementação e a disseminação de práticas educativas que estimulem o protagonismo estudantil, o pensamento crítico, a pesquisa, a colaboração e o uso consciente das tecnologias. Também considera o potencial da cultura maker na formação dos estudantes e em suas relações com a sociedade e o mundo do trabalho.',
    NULL,
    'Gabriel Aprigliano Fernandes, doutor e mestre em Engenharia Civil e graduado em Desenho Industrial pela UFRJ, além de graduado em Artes pelo Centro Universitário Claretiano. Atua na orientação científica, no planejamento metodológico e na coordenação das atividades da linha de pesquisa.',
    'Gabriel Moraes e Lethycia Machado da Silva Lima. Atuam na coleta de dados, sistematização de informações, produção de materiais e apoio às ações acadêmicas.',
    'Integrar a cultura maker aos processos educacionais por meio de metodologias ativas, fabricação digital, prototipagem e desenvolvimento de projetos interdisciplinares que promovam a aprendizagem criativa e colaborativa.'
);